('TXT_KEY_MATRIARCH_ROULS_1', 'Asha of the First Choir'),
('TXT_KEY_MATRIARCH_ROULS_2', 'Vera of Seven Forms'),
('TXT_KEY_MATRIARCH_ROULS_3', 'The Patient Voice'),
('TXT_KEY_MATRIARCH_ROULS_4', 'Nera Remembering'),
('TXT_KEY_MATRIARCH_ROULS_5', 'Ilyth the Returned'),
('TXT_KEY_MATRIARCH_ROULS_6', 'Sel of the Quiet Passage'),
('TXT_KEY_MATRIARCH_ROULS_7', 'Mara of the Lattice'),
('TXT_KEY_MATRIARCH_ROULS_8', 'The Keeper of Names'),
('TXT_KEY_MATRIARCH_ROULS_9', 'Soma Everwatchful'),
('TXT_KEY_MATRIARCH_ROULS_10', 'Tala of the Open Door'),
('TXT_KEY_MATRIARCH_ROULS_11', 'Vey of Many Voices'),
('TXT_KEY_MATRIARCH_ROULS_12', 'The Second Witness'),
('TXT_KEY_MATRIARCH_ROULS_13', 'Anri of the Long Memory'),
('TXT_KEY_MATRIARCH_ROULS_14', 'The Gentle Commander'),
('TXT_KEY_MATRIARCH_ROULS_15', 'The Unbroken Thread'),
('TXT_KEY_MATRIARCH_ROULS_16', 'The Lasting Promise'),
('TXT_KEY_ROULS_DIPLO_FIRST_GREETING_1', 'I am Trent Rou''ls. This is the form I wear today. We welcome you to the company of the living, however briefly you intend to remain.'),
('TXT_KEY_ROULS_DIPLO_GREETING_NEUTRAL_HELLO_1', 'Another meeting, another body. What shall we preserve between us?'),
('TXT_KEY_ROULS_DIPLO_GREETING_POLITE_HELLO_1', 'A familiar voice is always welcome. Come, let us speak.'),
('TXT_KEY_ROULS_DIPLO_GREETING_HOSTILE_HELLO_1', 'You have returned. We were beginning to hope you had learned discretion.'),
('TXT_KEY_ROULS_DIPLO_GREETING_AT_WAR_HOSTILE_1', 'How many more bodies will you spend to prove that you can break them?'),
('TXT_KEY_ROULS_DIPLO_DECLAREWAR_1', 'You mistake the vessel for the passenger. We will teach you the difference.'),
('TXT_KEY_ROULS_DIPLO_DOW_GENERIC_1', 'Your armies wear their flesh with such certainty. Let us loosen the fit.'),
('TXT_KEY_ROULS_DIPLO_ATTACKED_1', 'So you have chosen to break our bodies. Very well. We have others.'),
('TXT_KEY_ROULS_DIPLO_DEFEATED_1', 'The flesh is a coat. Remember that, when you hear our voices again.'),
('TXT_KEY_ROULS_DIPLO_PEACE_OFFER_1', 'Enough vessels have been broken. Let us preserve what still remembers.'),
('TXT_KEY_ROULS_DIPLO_NO_PEACE_1', 'We have only just begun returning. Your war is not finished.'),
('TXT_KEY_ROULS_DIPLO_AGREE_SHORT_1', 'The Choir agrees.'),
('TXT_KEY_ROULS_DIPLO_DISAGREE_SHORT_1', 'That will not survive consideration.'),
('TXT_KEY_ROULS_DIPLO_LETS_HEAR_IT_1', 'Speak. We are listening with more than one lifetime.'),
('TXT_KEY_ROULS_DIPLO_LETSHEARIT_1', 'Speak. We are listening with more than one lifetime.'),
('TXT_KEY_ROULS_DIPLO_GOODBYE_1', 'Wear it well, and pass it on.'),
('TXT_KEY_ROULS_DIPLO_TRADE_ACCEPT_GENEROUS_1', 'A thoughtful offering. The memory of this will endure.'),
('TXT_KEY_ROULS_DIPLO_TRADE_ACCEPT_ACCEPTABLE_1', 'A fair exchange. Let it be done.'),
('TXT_KEY_ROULS_DIPLO_TRADE_REJECT_INSULTING_1', 'We have worn foolish bodies before. We do not need a foolish bargain.'),
('TXT_KEY_ROULS_DIPLO_TRADE_REJECT_UNACCEPTABLE_1', 'These terms do not carry enough value.'),
('TXT_KEY_ROULS_DIPLO_WORK_WITH_US_1', 'Our peoples could preserve more together. Shall we make that promise?'),
('TXT_KEY_ROULS_DIPLO_WORK_WITH_US_YES_1', 'A promise worth remembering. We accept.'),
('TXT_KEY_ROULS_DIPLO_RESPONSE_TO_BEING_DENOUNCED_1', 'You address a body and mistake it for the limit of our patience.'),
('TXT_KEY_ROULS_DIPLO_THANKFUL_1', 'We will remember this kindness, long after these hands have faded.');
